#!/usr/bin/env python3
"""Minimal UCI engine that always plays the move most favorable to the opponent.

Used as a drop-in replacement so the game opponent blunders. Speaks UCI.
"""
import sys
import chess

def best_for_opponent(board: chess.Board) -> chess.Move:
    # Prefer moves that hang the most material / walk into mate, judged by a
    # simple static eval after the move (from White's perspective we want the
    # score as low as possible, i.e. worst for the side to move if side is White).
    # Since this engine plays White, choose the legal move minimizing White's material.
    def mat(b):
        vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
        s = 0
        for pt, v in vals.items():
            s += v * (len(b.pieces(pt, chess.WHITE)) - len(b.pieces(pt, chess.BLACK)))
        return s
    worst = None
    worst_score = 10**9
    for m in board.legal_moves:
        board.push(m)
        if board.is_checkmate():
            sc = -10**6
        else:
            sc = mat(board)
            # also prefer giving check to opponent? no, we want to lose: prefer
            # being in check ourselves after? irrelevant. Penalize captures of black
            # pieces so we don't take material.
        board.pop()
        if sc < worst_score or worst is None:
            worst_score = sc
            worst = m
    return worst

def main():
    board = chess.Board()
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == "uci":
            print("id name Weakling", flush=True)
            print("id author local", flush=True)
            print("option name Skill Level type spin default 20 min 0 max 20", flush=True)
            print("uciok", flush=True)
        elif line == "isready":
            print("readyok", flush=True)
        elif line == "ucinewgame":
            board = chess.Board()
        elif line.startswith("setoption"):
            pass
        elif line.startswith("position"):
            parts = line.split()
            if "startpos" in parts:
                board = chess.Board()
                if "moves" in parts:
                    for u in parts[parts.index("moves")+1:]:
                        board.push_uci(u)
            elif "fen" in parts:
                idx = parts.index("fen")
                fen_parts = []
                i = idx+1
                while i < len(parts) and parts[i] != "moves":
                    fen_parts.append(parts[i]); i += 1
                board = chess.Board(" ".join(fen_parts))
                if "moves" in parts:
                    for u in parts[parts.index("moves")+1:]:
                        board.push_uci(u)
        elif line.startswith("go"):
            mv = best_for_opponent(board)
            print(f"bestmove {mv.uci()}", flush=True)
        elif line == "quit":
            break

if __name__ == "__main__":
    main()
